const PROFILE_DATA = {"_meta":{"file":"profile.json","purpose":"综合性格总结文案库。由三维融合后的大五平均向量驱动，生成整体人格叙述。","evidenceLevel":"heuristic","srcId":["bigfive_costa1992","synthesis_heuristic"],"disclaimer":"本文案库依据大五人格各维度的学术定义撰写描述性文本。维度定义本身有实证基础（Costa & McCrae, 1992），但『由三维融合向量生成总结』是本项目的启发式设计。总结反映的是你所填写的三套描述体系融合后的画像，不是独立的人格测量结果。","designNote":"每条特质轴分高/中/低三档（≥62 / 39-61 / ≤38），各档提供叙述句、做事风格、人际风格、优势、建议五类文案。原型分两套：archetypes 由两条最突出轴的组合匹配；contrastArchetypes 由最大分歧轴匹配，用于三维说法互相打架时——此时平均向量会把反差抹平，只有分歧轴能反映真实特点。"},"thresholds":{"high":62,"low":38},"axisText":{"extraversion":{"high":{"narrative":"你的能量明显朝外流动。人多的场合让你活跃起来，想法常常是在与人交谈的过程中才逐渐成形","work":"习惯边讨论边推进，比起一个人闷头研究，你更愿意把问题摊到桌面上聊","social":"主动建立连接，是把气氛带起来的那个人","strength":"感染力与推动力强，能迅速打开局面","advice":"留一点独处的时间给自己。持续的社交输出会掩盖内在真正的判断"},"mid":{"narrative":"你在社交与独处之间保持着弹性。需要热闹时能进入状态，需要安静时也不会觉得难受","work":"既能参与协作讨论，也能独立完成需要专注的任务","social":"不刻意扩张也不刻意回避，关系维持在舒服的密度","strength":"社交弹性好，在不同场合都能找到合适的位置","advice":"这种平衡是优势，但也容易在两边都不彻底。重要场合可以有意识地选一种模式"},"low":{"narrative":"你的能量朝内收敛。独处不是逃避，而是真正在恢复；热闹之后你需要时间才能缓过来","work":"在安静、少打扰的环境里效率最高，习惯先想清楚再开口","social":"关系不多但深，更愿意跟少数人认真聊，而不是跟很多人泛泛而谈","strength":"专注度高，思考有深度，不容易被外界声音带走","advice":"适度让别人看见你的想法。你的判断常常很有价值，但沉默会让它被忽略"}},"openness":{"high":{"narrative":"你对新事物有天然的胃口。抽象的概念、还没成型的可能性，这些比眼前确定的东西更能吸引你","work":"擅长从不同角度找思路，但对重复性、流程化的工作耐性有限","social":"对差异接受度高，愿意听不同立场的说法","strength":"想象力与联想能力强，容易在别人看不出关联的地方找到连接","advice":"给一部分想法真正落地的机会。开放性的风险是想得多、留下的少"},"mid":{"narrative":"你既接受新东西，也尊重已经验证过的方法。不排斥变化，但也不为了新而新","work":"能在创新与稳妥之间做取舍，通常给出可执行的方案","social":"对不同观点持开放态度，同时有自己的判断底线","strength":"务实的创造力——想法不脱离现实","advice":"在需要突破的场合，可以让自己再大胆一点"},"low":{"narrative":"你更信任经验和实证。看得见、摸得着、被验证过的东西才让你放心","work":"偏好清晰的方法与先例可循的路径，执行扎实少出错","social":"对熟悉的人和环境投入更多，不太追求新鲜刺激","strength":"务实可靠，不容易被空洞的概念带偏","advice":"偶尔接触一下自己不熟悉的领域。守成的风险是错过真正的转折点"}},"conscientiousness":{"high":{"narrative":"你有清晰的秩序感。计划、清单、截止时间不是负担，而是让你安心的东西","work":"目标明确、执行到底，答应的事情基本不会掉","social":"被视为可托付的类型，别人愿意把重要的事交给你","strength":"自律与坚持，长期目标的完成率高","advice":"允许计划出现意外。过高的标准容易变成对自己的持续消耗"},"mid":{"narrative":"你有基本的计划意识，但不被计划绑死。该收紧时能收紧，该灵活时也放得开","work":"在结构与弹性之间取平衡，能应对计划外的变动","social":"履约但不僵化，相处起来没有压迫感","strength":"既靠得住，又不会因为一点偏差就失控","advice":"对真正重要的目标，可以给自己更明确的约束"},"low":{"narrative":"你的节奏是随机应变型的。过于严密的安排让你不适，你更相信当下的判断","work":"临场应变能力强，但长线推进和收尾环节容易松","social":"相处轻松没有束缚感，不太拘泥形式","strength":"灵活开放，机会来的时候能立刻调整方向","advice":"给最重要的那一两件事设一个硬性节点。灵活的代价往往是重要的事被一直推后"}},"agreeableness":{"high":{"narrative":"你天生会注意到别人的感受。谁被忽略了、谁不太自在，这些你往往先察觉到","work":"重视协作氛围，愿意为团队的和谐做出让步","social":"共情能力强，是别人愿意倾诉的对象","strength":"温和包容，能把关系维护得很稳","advice":"练习说不。过度体贴容易让自己的需求被排到最后"},"mid":{"narrative":"你在体贴与直率之间有分寸。会照顾别人的感受，但不会因此放弃自己的立场","work":"既能配合团队，也能在必要时坚持自己的判断","social":"待人有温度也有边界","strength":"既不冷硬也不迁就，关系里的分寸感好","advice":"在真正重要的分歧上，可以把立场表达得更明确一些"},"low":{"narrative":"你更看重事情本身的对错，而不是话说得好不好听。对你来说，把问题讲清楚比让场面好看更重要","work":"讨论问题直接，习惯指出逻辑上站不住的地方","social":"不擅长客套，但认识久了会知道你是真诚的","strength":"客观理性，不会被人情因素影响判断","advice":"同样的意思换一种说法，接受度差别很大。表达方式是可以练的"}},"stability":{"high":{"narrative":"你的情绪底盘比较稳。压力来的时候不容易失控，事情过去了也不会反复咀嚼","work":"在高压和不确定的环境下依然能保持判断力","social":"情绪不太外溢，别人在你身边会感到安定","strength":"抗压能力强，恢复得快","advice":"稳定不等于要压住所有感受。适度表达情绪反而让关系更近"},"mid":{"narrative":"你的情绪有起伏但在可控范围。压力大时会受影响，但通常能自己走出来","work":"多数情况下能稳定输出，极端压力下需要一些缓冲","social":"情绪真实但不失控","strength":"既有感受力，也有基本的自我调节能力","advice":"识别自己的压力信号，提前给自己留出恢复的时间"},"low":{"narrative":"你对自己要求高，也因此容易内耗。一个小失误可能在心里过很久，做完决定还会反复回想","work":"对细节和品质敏感，但容易因为担心不够好而迟迟不动手","social":"对他人情绪敏感，也更容易被评价影响","strength":"这份敏感是洞察力的来源，也是你不断进步的动力","advice":"区分「有用的反思」和「无意义的反复」。前者带来改进，后者只消耗你"}}},"archetypes":[{"keys":["extraversion:high","openness:high"],"name":"开拓型","face":"🚀","title":"点子多、推得动的开拓者","desc":"你既有源源不断的想法，也有把想法说出去、带着人一起干的能量。你的价值在开局阶段最明显。"},{"keys":["extraversion:high","conscientiousness:high"],"name":"统筹型","face":"🎬","title":"能把人和事都安排到位的统筹者","desc":"你有组织力也有推动力，混乱的局面到你手上会逐渐变得有秩序。别人习惯在关键时刻看向你。"},{"keys":["extraversion:high","agreeableness:high"],"name":"凝聚型","face":"🤗","title":"让一群人愿意待在一起的凝聚者","desc":"你在意每个人是否被照顾到，也有能力把这份在意变成实际的关系维护。团队的温度往往由你决定。"},{"keys":["openness:high","conscientiousness:high"],"name":"架构型","face":"🏗️","title":"想得远也做得实的架构者","desc":"你能看到长远的可能性，同时愿意为它铺设具体的路径。这个组合稀少，因为想象力与执行力常常互斥。"},{"keys":["openness:high","stability:low"],"name":"创作型","face":"🎨","title":"敏感而富有创造力的创作者","desc":"你的感受力细腻，想象空间宽阔。这份敏感带来内耗，但也正是你作品与洞察的来源。"},{"keys":["openness:high","agreeableness:high"],"name":"共情型","face":"🌿","title":"理解力与共情力兼具的倾听者","desc":"你能理解不同的立场，也真心在意对方的处境。别人在你面前愿意说真话。"},{"keys":["conscientiousness:high","stability:high"],"name":"定盘型","face":"⚓","title":"可托付的定盘者","desc":"你说了就会做到，压力下也不会乱。你不追求耀眼，但你在的地方事情就是稳的。"},{"keys":["conscientiousness:high","agreeableness:low"],"name":"执行型","face":"⚙️","title":"讲效率、重结果的执行者","desc":"你目标清晰、行动直接，不太在流程和客套上花时间。你要的是事情真正被完成。"},{"keys":["conscientiousness:high","agreeableness:high"],"name":"守护型","face":"🛡️","title":"细致周全的守护者","desc":"你把责任感和体贴结合在一起，会记住别人忽略的细节，并且默默把它处理好。"},{"keys":["extraversion:low","openness:high"],"name":"思辨型","face":"🔭","title":"安静但思考很深的探索者","desc":"你不需要外界的热闹，你的世界在内部展开。你的想法常常独立于主流，且经过反复推演。"},{"keys":["extraversion:low","conscientiousness:high"],"name":"笃行型","face":"🌱","title":"沉静而扎实的笃行者","desc":"你不太宣告自己在做什么，但你的进度从不落下。时间会证明这种方式的力量。"},{"keys":["extraversion:low","agreeableness:high"],"name":"陪伴型","face":"🍃","title":"安静而可靠的陪伴者","desc":"你的关心不响亮但持续。你记得别人的小事，也在需要的时候一直都在。"},{"keys":["extraversion:low","stability:low"],"name":"内省型","face":"🌙","title":"敏感深思的内省者","desc":"你的内在世界丰富且活跃，感受比大多数人更细。这让你辛苦，也让你比别人看得更透。"},{"keys":["agreeableness:low","stability:high"],"name":"冷静型","face":"🧊","title":"客观冷静的分析者","desc":"你不容易被情绪和人情牵动，能在混乱中保持判断。需要有人做冷静决定时，那个人往往是你。"},{"keys":["conscientiousness:low","extraversion:high"],"name":"灵活型","face":"🎈","title":"随机应变的行动派","desc":"你不喜欢被计划框住，靠临场感觉走。机会出现时你反应最快，代价是长线的坚持。"},{"keys":["conscientiousness:low","openness:high"],"name":"自由型","face":"🕊️","title":"不受拘束的自由灵魂","desc":"你的兴趣跟着好奇心走，不为形式所限。你活得比大多数人自在，也更容易半途转向。"}],"fallbackArchetype":{"name":"均衡型","face":"⚖️","title":"各方面都比较均衡的调和者","desc":"你没有特别极端的特质，各个方向都保持在中间地带。这种均衡让你适应性强，在不同环境里都不至于失衡，但也意味着你的鲜明标签不明显。"},"_contrastNote":"反差型原型。⚠️ 为什么需要单独一套：把两个极端取平均会把反差抹平——INFP 的外向性 32 与白羊座的 78 平均成 55，恰好落在中间档，常规匹配只能回退到「均衡型」，输出「你没有特别极端的特质」。但 46 分的落差恰恰说明这个人身上有强烈反差，那才是他最鲜明、最值得分享的标签。所以存在分歧时改由「分歧轴」驱动匹配：不看平均值，看两个体系在哪里打架，再把「打架」本身命名成一个原型。keys 填分歧轴的 axis key（单元素数组）；gapMin 是分歧强度门槛，引擎取满足 gapMin ≤ 实际分差的原型中门槛最高的那个，因此同一轴可设多档（如 30 温和反差 / 45 明显反差 / 60 极端反差）。","contrastArchetypes":[{"keys":["extraversion"],"gapMin":50,"name":"闷雷型","face":"⛈️","title":"平时闷着，一响就是闷雷","desc":"你在人群里几乎不出声，常被当成背景板。但真正轮到你的时候——或者被逼到某个点上——你会突然全力输出，声音大得连自己都意外。之后又退回安静，像什么都没发生过。见过你这一面的人通常不会再觉得你好欺负。","contrastLine":"我平时不出声，不代表我没有声音"},{"keys":["extraversion"],"gapMin":45,"name":"静燃型","face":"🌋","title":"慢热，但点着了就烧很久","desc":"你在不熟的人面前话很少，需要先观察、先确认安全。可一旦认定这个人、这件事，你会比谁都投入，能量放得又猛又久。很多人只见过你的第一面，一直没等到第二面——那不是冷淡，是你还在判断值不值得。","contrastLine":"安静是我的默认状态，不是我的上限"},{"keys":["extraversion"],"gapMin":30,"name":"双频型","face":"📻","title":"熟人和陌生人，看到的是两个你","desc":"你的外向程度取决于对面坐着的是谁。安全的人面前你能聊一整晚，不熟的场合一句话都嫌多。这不是装，也不是社恐，是你只把能量花在值得的地方——你只是没打算对谁都热情。","contrastLine":"不是我双面，是我只把能量给值得的人"},{"keys":["openness"],"gapMin":49,"name":"脱缰型","face":"🐎","title":"一半在算风险，一半在想出走","desc":"你脑子里同时住着一个精算师和一个流浪汉：一边把计划做得滴水不漏，一边随时想推翻重来。别人觉得你善变，其实你只是既想要安全感，又受不了没有新鲜感——两个念头都是真的，而且都很强烈。","contrastLine":"我想出走，但我一定会先订好回程票"},{"keys":["openness"],"gapMin":45,"name":"风筝型","face":"🪁","title":"想法飞得很远，脚还踩在地上","desc":"你能想出别人想不到的东西，也真的会被新东西吸引。但到了要投入的时候，你会回到最稳妥的那条路。不是不敢冒险，是你分得清哪个冒险值得——一直飘着的人飞不远，太实的人又没什么意思。","contrastLine":"我的想象力有刹车，但刹车不是一直踩着"},{"keys":["openness"],"gapMin":30,"name":"探路型","face":"🧭","title":"愿意试新东西，但不轻易 all in","desc":"你对新鲜事有兴趣，也愿意尝试，但从不会一头扎进去。先小规模试一下，看清楚了再决定要不要投入。别人觉得你既开放又保守，其实你只是不喜欢失去控制的感觉。","contrastLine":"我愿意试，但得先看清出口在哪儿"},{"keys":["conscientiousness"],"gapMin":45,"name":"弹簧型","face":"🌀","title":"平时很散，紧要关头比谁都较真","desc":"你日常看起来挺随性：东西乱放、计划常改、临到 deadline 才开始动。但真到要交付的时候，或者碰上你在意的事，你会突然变得极有条理，甚至有点较真。你的秩序不是常态，是按需启动的。","contrastLine":"我平时可以很散，但紧要关头比谁都较真"},{"keys":["conscientiousness"],"gapMin":30,"name":"留白型","face":"📓","title":"有计划，但永远给意外留一格","desc":"你会做计划，也确实按计划推进，但从不会把行程排满。你清楚安排太紧的话，一旦被打乱就会全线崩掉，所以习惯性地留出弹性。这种松弛不是不上心，是吃过亏之后练出来的。","contrastLine":"我的计划表永远留一格，专门给意外"},{"keys":["agreeableness"],"gapMin":40,"name":"温刃型","face":"🗡️","title":"平时好说话，触到底线不含糊","desc":"你大多数时候温和、好商量，能体谅别人的难处，也不爱争。但一旦碰上你认定的原则或者真相，你会直接说出来，一点也不绕。很多人第一次见你这一面都会愣一下，之后反而更信任你。","contrastLine":"我很好说话，但我有不能让的地方"},{"keys":["agreeableness"],"gapMin":30,"name":"分寸型","face":"🎚️","title":"该温和时温和，该直接时直接","desc":"你知道什么时候该顾着别人的感受，也知道什么时候实话必须说出口。这不是圆滑，是你同时在意关系和事实，舍不得丢掉任何一个。跟你相处的人通常会觉得：舒服，但不糊弄。","contrastLine":"我会看场合说话，但每句话都是真的"},{"keys":["stability"],"gapMin":45,"name":"深水型","face":"🌊","title":"里面翻涌，外面看不出来","desc":"你感受到的东西比大多数人深，情绪来得快、幅度也大。但你不常表现出来——很多时候你已经在里面翻江倒海了，外面看着还很平静。这种反差让你比别人更容易受伤，也比别人恢复得更快。","contrastLine":"我不是不难过，我只是不难过给别人看"},{"keys":["stability"],"gapMin":30,"name":"韧弦型","face":"🎻","title":"会晃得很明显，但从没真正断过","desc":"你的情绪有起伏，会因事烦躁、低落，甚至短暂失控。但你从没真的垮掉，起伏之后总能回到原位，有时候还比之前更稳。敏感和扛得住，在你身上是同一件事的两面。","contrastLine":"我会晃得很明显，可我从来没真正断过"}],"consistencyInsight":{"high":"三套体系对你的描述高度重合，说明这个画像在不同角度下都成立，可信度相对高一些。","mid":"三套体系整体方向一致，但在个别特质上说法不同。这些分歧的地方往往是你身上最有张力的部分。","low":"三套体系对你的描述差异很大。这通常不是某套错了，而是你本身就有好几副面貌——不同情境下会切到不同的一面。反差大的人适应面往往更广，只是很难被一个标签说全。（需要说明的是：这里的「一致性」只衡量三套说法彼此吻合的程度，不衡量任何一方的可靠性。）","single":"你只填写了一个维度，这份总结完全基于它。补充其他维度后，可以看到不同体系之间的相互印证与分歧。"}};

