const SHARE_COPY_DATA = {"_meta":{"file":"share-copy.json","purpose":"分享文案模板库。6 类风格 × 多套模板，支持变量插值与轮换去重。","designNote":"模板化的核心是变量丰富度。每套模板只声明结构，具体内容由用户数据填充，因此同一模板给不同用户看到的结果差异很大。contrast（反差式）是专为「三维说法互相打架」的场景设计的：它不回避分歧，而是把「两套体系各执一词」本身当卖点讲——反差感比一致性更像一个人，也更容易引发评论区互动。","lengthGuide":{"wechat_moments":{"max":120,"note":"朋友圈折叠阈值约 112 字，超出会显示「全文」"},"weibo":{"max":140,"note":"微博单条上限"},"xiaohongshu":{"max":200,"note":"小红书正文首屏"},"short":{"max":60,"note":"极简版，适合配图发送"}},"variables":{"archetype":"人格原型名，如「开拓型」","archetypeTitle":"原型副标题，如「点子多、推得动的开拓者」","animal":"MBTI 动物形象名，如「做梦小蝴蝶」","mbti":"MBTI 类型码，如 INFP","mbtiCn":"MBTI 中文名，如「调停者」","oneLiner":"一句话概括","score":"三维一致性百分比数字","scoreLabel":"一致性等级，如「高度一致」","rarity":"人口占比，如 1.5%","topTrait":"最突出特质，如「求新好奇」","topTraitVal":"该特质分值","secondTrait":"第二突出特质","dimCount":"填写的维度数量","dimList":"维度列表，如「MBTI + 星座 + 八字」","zodiac":"星座名","dayMaster":"八字日主，如「庚金」","strength":"首要优势描述","advice":"首要建议描述","conflictAxis":"分歧最大的特质轴名","badge":"首个成就徽章文案","traitSpan":"五维最高分与最低分之差，衡量均衡度","lowTrait":"最低分特质的低端标签","lowTraitVal":"最低分特质分值","maxTrait":"五维最高分","minTrait":"五维最低分","secondTraitVal":"第二突出特质分值","topAxis":"最突出特质所属轴名","rarityNum":"人口占比数值版（用于条件比较）","allMid":"五维是否全部落在中段","splitAxis":"分歧最大的特质轴中文名，如「外向性」","splitGap":"该轴上的分歧分值差，如 46","splitHighLabel":"分歧轴高分端的中文标签，如「外向活跃」","splitLowLabel":"分歧轴低分端的中文标签，如「沉静内敛」","splitHighWho":"给出高分说法的维度名，如「星座」","splitLowWho":"给出低分说法的维度名，如「MBTI」","contrastLine":"反差型原型的金句（contrastArchetypes 的 contrastLine）"}},"styles":{"suspense":{"name":"悬念式","icon":"🔮","desc":"不直接说结论，留钩子让人想点开","templates":[{"id":"sus-01","text":"测完发现，我居然是「{archetype}」。\n\n{oneLiner}\n\n最意外的是三套体系居然吻合了 {score}%……","needs":["score"]},{"id":"sus-02","text":"{dimList} 交叉验证之后，我看到了一个不太想承认、但确实是我的答案。\n\n「{archetype}」","needs":["dimList"]},{"id":"sus-03","text":"本来是抱着玩的心态测的。\n\n结果它说我是「{archetype}」，还说我「{topTrait}」——这个我确实没法反驳。","needs":["topTrait"]},{"id":"sus-04","text":"最准的一句是这个：\n\n「{oneLiner}」\n\n不是某一套说了算，是 {dimList} 交叉算出来的。有点服。","needs":["dimList"]},{"id":"sus-05","text":"全球只有 {rarity} 的人是我这一型。\n\n难怪总觉得有些话说出来别人不太懂。","needs":["rarity"]},{"id":"sus-06","text":"分歧最大的居然是「{conflictAxis}」——MBTI 和星座给了我完全相反的说法。\n\n所以我到底是哪个？","needs":["conflictAxis"]}]},"resonance":{"name":"共鸣式","icon":"💭","desc":"说出被说中的感受，引发同型认同","templates":[{"id":"res-01","text":"{mbti}「{mbtiCn}」+ {zodiac}，测出来是「{archetype}」。\n\n看到这句直接沉默了：{oneLiner}","needs":["zodiac","mbti","mbtiCn"]},{"id":"res-02","text":"「{advice}」\n\n——这条建议，看得我有点想关掉页面。","needs":["advice"]},{"id":"res-03","text":"我是「{archetype}」，{archetypeTitle}。\n\n被说中的部分：{strength}\n不太想面对的部分：{advice}","needs":["strength","advice"]},{"id":"res-04","text":"原来我不是奇怪，我是「{archetype}」。\n\n{oneLiner}\n\n有同类吗？举个手。","needs":[]},{"id":"res-05","text":"{topTrait} {topTraitVal} 分。\n\n这个数字解释了我这些年很多莫名其妙的选择。","needs":["topTrait","topTraitVal"]},{"id":"res-06","text":"{dimList} 都提到我「{topTrait}」。\n\n几套完全不同的体系，居然在这一点上说得差不多。那大概是真的了。","needs":["dimList","topTrait"]}]},"humor":{"name":"幽默式","icon":"😆","desc":"自嘲或反差感，降低炫耀味","templates":[{"id":"hum-01","text":"AI 说我是「{archetype}」，形象是{animal}。\n\n我一个成年人，被概括成了一只{animal}。","needs":["animal"]},{"id":"hum-02","text":"花了 6 分钟做题，得到一句「{oneLiner}」\n\n钱花得值（免费的）。","needs":[]},{"id":"hum-03","text":"{dimList}，几个说法吵了半天，最后吻合度 {score}%。行吧，各让一步。","needs":["dimList","score"]},{"id":"hum-04","text":"优势：{strength}\n建议：{advice}\n\n翻译一下就是——继续这样，但别太这样。","needs":["strength","advice"]},{"id":"hum-05","text":"测出来是「{archetype}」，配图是只{animal}。\n\n本来想反驳，看了一眼那个表情，确实挺像我上班时候的样子。","needs":["animal"]},{"id":"hum-06","text":"它说我{topTrait}（{topTraitVal}分）。\n\n分数这么高，是不是该找个地方兑换点什么。","needs":["topTrait","topTraitVal"]}]},"flex":{"name":"成就炫耀式","icon":"🏆","desc":"突出稀有度与数据亮点","templates":[{"id":"flx-01","text":"🏆 {badge}\n\n人格原型「{archetype}」— {archetypeTitle}\n三维吻合度 {score}%（{scoreLabel}）","needs":["badge","score","scoreLabel"]},{"id":"flx-02","text":"{mbti} · 全球仅 {rarity}\n\n「{archetype}」{archetypeTitle}\n\n稀有度这块我先站个位。","needs":["rarity","mbti"]},{"id":"flx-03","text":"{dimList} 交叉验证：吻合度 {score}%，{scoreLabel}。\n\n我这个人，还挺自洽的。","needs":["dimList","score","scoreLabel"]},{"id":"flx-04","text":"{topTrait} {topTraitVal} · {secondTrait}\n\n「{archetype}」认证完毕。","needs":["topTrait","topTraitVal","secondTrait"]},{"id":"flx-05","text":"{dimCount} 个维度交叉完成 ✅\n{dimList}\n\n结论：「{archetype}」，{oneLiner}","needs":["dimCount","dimList"]}]},"contrast":{"name":"反差式","icon":"⚡","desc":"把两套体系的打架讲成卖点，反差本身就是标签","templates":[{"id":"con-01","text":"两套体系在我身上吵起来了。\n{splitHighWho}说我「{splitHighLabel}」，{splitLowWho}说我「{splitLowLabel}」，差 {splitGap} 分。\n\n两个我都认。","needs":["splitHighWho","splitLowWho","splitHighLabel","splitLowLabel","splitGap"]},{"id":"con-02","text":"{splitLowWho}说我「{splitLowLabel}」，{splitHighWho}说我「{splitHighLabel}」，差 {splitGap} 分。\n\n我以前觉得这是矛盾，现在觉得这是配置。","needs":["splitHighWho","splitLowWho","splitHighLabel","splitLowLabel","splitGap"]},{"id":"con-03","text":"测出来我在「{splitAxis}」上差了 {splitGap} 分。\n\n认识我的人应该都见过这两面，只是不同时出现。","needs":["splitAxis","splitGap"]},{"id":"con-04","text":"我是「{archetype}」——{archetypeTitle}。\n\n{splitHighWho}和{splitLowWho}在「{splitAxis}」上差了 {splitGap} 分。\n\n反差这么大的还有谁？","needs":["archetype","archetypeTitle","splitHighWho","splitLowWho","splitAxis","splitGap"]},{"id":"con-05","text":"「{contrastLine}」\n\n——{splitHighWho}说我{splitHighLabel}，{splitLowWho}说我{splitLowLabel}，差了 {splitGap} 分。","needs":["contrastLine","splitHighWho","splitLowWho","splitHighLabel","splitLowLabel","splitGap"]},{"id":"con-06","text":"有个数字我一直没想通：{splitGap}。\n\n同一个我，{splitHighWho}说{splitHighLabel}，{splitLowWho}说{splitLowLabel}——差这么多。","needs":["splitGap","splitHighWho","splitLowWho","splitHighLabel","splitLowLabel"]},{"id":"con-07","text":"{splitLowWho}说我{splitLowLabel}，{splitHighWho}说我{splitHighLabel}。\n\n差 {splitGap} 分，愣是同一个人。\n\n我是「{archetype}」。","needs":["splitHighWho","splitLowWho","splitHighLabel","splitLowLabel","splitGap","archetype"]},{"id":"con-08","text":"{splitLowWho}说我{splitLowLabel}，{splitHighWho}说我{splitHighLabel}。\n\n两个都对。{archetypeTitle}——说的大概就是这个。","needs":["splitHighWho","splitLowWho","splitHighLabel","splitLowLabel","archetypeTitle"]},{"id":"con-09","text":"{splitHighWho}说我{splitHighLabel}，{splitLowWho}说我{splitLowLabel}。\n\n我以前总觉得自己前后矛盾，原来两套说法都对——只是不同时候的我。","needs":["splitHighWho","splitLowWho","splitHighLabel","splitLowLabel"]}]},"minimal":{"name":"极简式","icon":"◾","desc":"配图发送，文字只做点题","templates":[{"id":"min-01","text":"「{archetype}」\n{oneLiner}","needs":[]},{"id":"min-02","text":"{mbti} · {archetype}\n三维吻合度 {score}%","needs":["score","mbti"]},{"id":"min-03","text":"{oneLiner}","needs":[]},{"id":"min-04","text":"我是一只{animal}。\n（认证过的）","needs":["animal"]},{"id":"min-05","text":"{topTrait}、{secondTrait}。\n\n就这两个词，概括了我。","needs":["topTrait","secondTrait"]}]}},"cta":{"_note":"结尾引导语。{url} 会被替换为 site.url。short 列表用于长文案兜底，确保链接不被丢弃。","list":["你是哪一型？👉 {url}","来测测看你是什么 👉 {url}","好奇你们的结果 👉 {url}","评论区报个型？👉 {url}","三维交叉分析，比单看星座准 👉 {url}","48 题量表 + 星座 + 八字 👉 {url}"],"short":["👉 {url}","测测你的 👉 {url}"]},"badges":{"_note":"成就徽章。按条件动态解锁，用于分享图与炫耀式文案。⚠️ balanced（traitSpan<=28）依赖 share-engine.js 在存在分歧轴时把 traitSpan 置为 999：平均向量会把冲突两端抹平（32 与 78 平均成 55），跨度虚低，否则「五维均衡」会与「多面人格」成对出现、同一屏自相矛盾。","rules":[{"id":"ultra-rare","cond":"rarity<2","icon":"💎","label":"极稀有人格","sub":"全球仅 {rarity}","color":"#C4A9F5","weight":100},{"id":"rare","cond":"rarity<4","icon":"✨","label":"稀有人格","sub":"全球仅 {rarity}","color":"#8FC9F5","weight":90},{"id":"perfect-sync","cond":"score>=85","icon":"🎯","label":"三观高度统一","sub":"吻合度 {score}%","color":"#3FB98C","weight":95},{"id":"high-sync","cond":"score>=70","icon":"🔗","label":"三维吻合","sub":"吻合度 {score}%","color":"#7DDCC0","weight":70},{"id":"split-soul","cond":"score<45","icon":"🎭","label":"多面人格","sub":"反差强烈，不止一副面貌","color":"#EA7BA8","weight":85},{"id":"big-split","cond":"splitGap>=40","icon":"⚡","label":"反差 {splitGap} 分","sub":"{splitAxis}上两套说法相反","color":"#EA7BA8","weight":87},{"id":"extreme-trait","cond":"maxTrait>=76","icon":"🔥","label":"{topTrait}拉满","sub":"{topTraitVal} 分","color":"#FF8A6B","weight":88},{"id":"rare-low","cond":"minTrait<=34","icon":"🧊","label":"极致{lowTrait}","sub":"仅 {lowTraitVal} 分","color":"#8FC9F5","weight":80},{"id":"full-report","cond":"dimCount==3","icon":"🏅","label":"完整版报告","sub":"三维全解析","color":"#FFD84D","weight":60},{"id":"balanced","cond":"traitSpan<=28","icon":"⚖️","label":"五维均衡","sub":"各项都不走极端","color":"#C9C4D2","weight":82}]},"themes":{"_note":"分享图配色主题。同一结果随机取一种，增加再生成的动力。","list":[{"id":"sunlit","name":"暖阳","bg":"#FFFBF4","band":"#FFF3D6","ink":"#2B2233","accent":"#FF8A6B","sub":"#6B6076","deco":"#FFD84D"},{"id":"dusk","name":"薄暮","bg":"#FBF7FF","band":"#EFE6FF","ink":"#2B2233","accent":"#8B5CF6","sub":"#6B6076","deco":"#C4A9F5"},{"id":"mint","name":"清晨","bg":"#F7FDFA","band":"#DDF5EB","ink":"#2B2233","accent":"#3FB98C","sub":"#6B6076","deco":"#7DDCC0"},{"id":"night","name":"深夜","bg":"#2B2233","band":"#3A3145","ink":"#FFF6E5","accent":"#FFD84D","sub":"#B0A6BC","deco":"#8B7BD8"}]},"brand":{"name":"三维人格","en":"TRI·PERSONA","tagline":"MBTI × 星座 × 八字 三维交叉分析","mark":"◈"},"site":{"_note":"站点 URL，用于分享文案 CTA 拼接与分享图回链。部署到别处时改这里。","url":"https://cheche3811-bot.github.io/mbti/","shortLabel":"cheche3811-bot.github.io/mbti"}};

/* ---------- sources.json ---------- */
const SOURCES_DATA = {"_meta":{"file":"sources.json","purpose":"全部分析结论的出处登记表。每条结论通过 srcId 关联到此处。","evidenceLevels":{"empirical":{"label":"实证研究支持","desc":"有同行评审的实证研究支持，可重复验证","badgeColor":"#3FB98C"},"contested":{"label":"实证但有争议","desc":"存在实证研究，但学界对其信度或效度有明确争议","badgeColor":"#F2A63B"},"heuristic":{"label":"启发式推导","desc":"基于已有实证数据的推导设计，本身未经独立验证","badgeColor":"#8FC9F5"},"tradition":{"label":"传统文化说法","desc":"源自传统文化典籍，无现代实证支持，不具预测效力","badgeColor":"#C4A9F5"},"refuted":{"label":"已被实证否证","desc":"有严谨实证研究明确否证其预测效力","badgeColor":"#EA7BA8"}}},"sources":{"bigfive_costa1992":{"level":"empirical","title":"Revised NEO Personality Inventory (NEO-PI-R) 手册","authors":"Costa, P. T., & McCrae, R. R.","year":1992,"publisher":"Psychological Assessment Resources","note":"大五人格（Big Five / FFM）的标准测量工具，本项目统一特质轴的理论基础。大五模型是当代人格心理学中实证支持最充分的框架。"},"mbti_bigfive_mccrae1989":{"level":"empirical","title":"Reinterpreting the Myers-Briggs Type Indicator from the Perspective of the Five-Factor Model of Personality","authors":"McCrae, R. R., & Costa, P. T.","year":1989,"journal":"Journal of Personality, 57(1), 17-40","doi":"10.1111/j.1467-6494.1989.tb00759.x","note":"本项目 MBTI→大五 映射系数的直接来源。实测相关性：E-I 与外向性 r≈.74；S-N 与开放性 r≈.72；T-F 与宜人性 r≈.44；J-P 与尽责性 r≈.49。"},"mbti_reliability_pittenger2005":{"level":"contested","title":"Cautionary Comments Regarding the Myers-Briggs Type Indicator","authors":"Pittenger, D. J.","year":2005,"journal":"Consulting Psychology Journal: Practice and Research, 57(3), 210-221","note":"对 MBTI 的主要批评：重测信度不足（间隔 5 周后约 50% 受测者类型发生变化）；四维度实际呈连续正态分布而非双峰分布，二分归类缺乏统计依据。这是本项目将 MBTI 标注为 contested 的原因。"},"mbti_dichotomy_bess2002":{"level":"contested","title":"Bimodal Distributions? Testing an Assumption of the Myers-Briggs Type Indicator","authors":"Bess, T. L., & Harvey, R. J.","year":2002,"journal":"Journal of Personality Assessment, 78(2), 176-186","note":"实证检验发现 MBTI 各维度得分呈单峰正态分布，不支持「非此即彼」的类型学假设。本项目因此以百分比呈现倾向强度，并对 45-58% 区间标注「倾向不明显」。"},"mbti_capt_frequency":{"level":"empirical","title":"Estimated Frequencies of the Types in the United States Population","authors":"Center for Applications of Psychological Type (CAPT)","year":2003,"note":"本项目 16 型人口占比数据来源。基于美国人口抽样估计，非全球数据，中国大陆分布可能存在差异。"},"likert_1932":{"level":"empirical","title":"A Technique for the Measurement of Attitudes","authors":"Likert, R.","year":1932,"journal":"Archives of Psychology, 140, 1-55","note":"七级量表的方法学来源。相比二分强制选择，等距量表能保留倾向强度信息。"},"acquiescence_paulhus1991":{"level":"empirical","title":"Measurement and Control of Response Bias","authors":"Paulhus, D. L.","year":1991,"publisher":"In Measures of Personality and Social Psychological Attitudes, Academic Press","note":"默认同意倾向（acquiescence bias）的标准应对方案是正反向计分题平衡。本项目每维度正反向题严格 5:5（AT 维度 4:4）即出于此。"},"astro_carlson1985":{"level":"refuted","title":"A Double-Blind Test of Astrology","authors":"Carlson, S.","year":1985,"journal":"Nature, 318, 419-425","doi":"10.1038/318419a0","note":"发表于《自然》的双盲实验。占星师无法将人格问卷结果与对应星盘正确配对，准确率与随机猜测无显著差异。这是占星学缺乏预测效力最有力的实证证据之一。"},"astro_dean2003":{"level":"refuted","title":"Is Astrology Relevant to Consciousness and Psi?","authors":"Dean, G., & Kelly, I. W.","year":2003,"journal":"Journal of Consciousness Studies, 10(6-7), 175-198","note":"对超过 2000 名「时辰双生子」（出生时间极为接近者）的追踪研究，发现其性格与人生轨迹相似度并未高于随机配对。直接否证出生时刻决定性格的核心假设。"},"astro_hartmann2006":{"level":"empirical","title":"The Relationship Between Birth Date and Individual Differences in Personality and General Intelligence","authors":"Hartmann, P., Reuter, M., & Nyborg, H.","year":2006,"journal":"Personality and Individual Differences, 40(7), 1349-1362","note":"基于 15,000+ 样本，检验出生日期与人格及智力的关系，未发现任何有意义的关联。"},"astro_barnum_forer1949":{"level":"empirical","title":"The Fallacy of Personal Validation: A Classroom Demonstration of Gullibility","authors":"Forer, B. R.","year":1949,"journal":"Journal of Abnormal and Social Psychology, 44(1), 118-123","note":"巴纳姆效应（Forer effect）的原始研究。人们倾向于认为模糊、普适的人格描述精准符合自己。这解释了为何星座描述常令人产生「说得真准」的主观感受。"},"astro_tradition_ptolemy":{"level":"tradition","title":"Tetrabiblos（四书 / 占星四书）","authors":"Claudius Ptolemaeus（托勒密）","year":150,"note":"西方占星学的奠基文献，黄道十二宫的性格归属体系源出于此。本项目星座性格描述属于此传统体系的现代通俗版本，仅作文化参考。"},"astro_boundary_aa2024":{"level":"empirical","title":"The Astronomical Almanac","authors":"U.S. Naval Observatory & HM Nautical Almanac Office","year":2024,"note":"星座日期边界的天文依据。太阳过黄经 0°/30°/60°… 的时刻每年浮动约 ±1 天，因此交界日期附近的星座归属需以实际年份的天文数据为准。本项目使用平均值并对交界日主动提示。"},"bazi_sanmingtonghui":{"level":"tradition","title":"《三命通会》","authors":"万民英（明）","year":1578,"note":"明代命理学集成之作，十天干性格论述的主要传统来源。属传统文化典籍，无现代实证支持。"},"bazi_yuanhaiziping":{"level":"tradition","title":"《渊海子平》","authors":"徐大升（宋）· 唐锦池编订","year":1600,"note":"子平术（八字命理）的奠基文献，四柱排盘与五行生克体系的传统依据。属传统文化典籍。"},"bazi_ditianshui":{"level":"tradition","title":"《滴天髓》","authors":"刘基（传）· 任铁樵注","year":1848,"note":"论五行旺衰与格局的传统命理经典，本项目五行强弱解读的参考来源。属传统文化典籍。"},"bazi_ganzhi_calendar":{"level":"empirical","title":"干支纪日的连续性与儒略日换算","authors":"《中国天文年历》/ 紫金山天文台","year":2020,"note":"干支纪日自古连续未断，可与儒略日建立确定的数学换算关系。本项目以 1900-01-31（儒略日 2415051）为甲辰日基准推算日柱，此换算本身是可验证的历法计算，与命理解读的性质不同——历法准确，解读属传统说法。"},"bazi_lichun_year":{"level":"tradition","title":"命理年柱以立春为界的惯例","authors":"传统命理通例（见《渊海子平》《三命通会》）","year":1600,"note":"八字年柱换年以立春（太阳过黄经 315°，约 2 月 4 日）为界，而非农历正月初一或公历元旦。本项目采用此惯例，立春日期使用近似值。"},"bazi_true_solar_time":{"level":"empirical","title":"真太阳时与平太阳时的差异（时差方程）","authors":"天文学基础常识","year":2024,"note":"精确排盘需将钟表时间校正为出生地真太阳时，涉及经度时差（每偏离 15° 差 1 小时）与均时差（全年 -14 至 +16 分钟）。本项目未做此校正，时柱为近似值，此为已知局限。"},"synthesis_heuristic":{"level":"heuristic","title":"本项目三维交叉分析的映射设计","authors":"本项目设计","year":2026,"note":"将 MBTI、星座、八字三者统一映射到大五人格五轴，再以余弦相似度计算一致性——这是本项目的设计推导，并非已发表的实证发现。MBTI→大五 的映射有实证基础（McCrae & Costa 1989），星座与八字→大五 的映射则是依据其传统性格描述文本进行的语义归纳，无实证依据。因此「一致性百分比」应理解为『三套描述体系在文字层面的吻合程度』，而非任何科学测量结果。"},"cosine_similarity":{"level":"empirical","title":"余弦相似度在人格剖面比较中的应用","authors":"Cronbach, L. J., & Gleser, G. C.","year":1953,"journal":"Psychological Bulletin, 50(6), 456-473","note":"人格剖面（profile）相似性的度量方法。本项目用余弦相似度比较三个维度的特质向量，方法本身成立，但输入向量的效度取决于各维度自身的效度。"}}};

